        tr:nth-child(even):hover {{ background: #f0f4f8; }}
        .milestone-list {{
            list-style: none;
            margin: 20px 0;
        }}
        .milestone-list li {{
            padding: 14px 0;
            border-bottom: 1px solid #e2e8f0;
            display: flex;
            align-items: flex-start;
        }}
        .milestone-list li:last-child {{ border-bottom: none; }}
        .era-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
            margin: 30px 0;
        }}
        .era-card {{
            background: linear-gradient(to bottom right, #f7fafc, #edf2f7);
            padding: 28px;
            border-radius: 10px;
            border-left: 4px solid var(--gold);
        }}
        .era-card h4 {{
            color: var(--primary);
            font-size: 1.1rem;
            margin-bottom: 12px;
        }}
        .era-card p {{ font-size: 0.95rem; margin: 0; }}
        .takeaway-list {{
            counter-reset: takeaway;
            list-style: none;
        }}
        .takeaway-list li {{
            counter-increment: takeaway;
            padding: 20px 0 20px 60px;
            position: relative;
            border-bottom: 1px solid #e2e8f0;
        }}
        .takeaway-list li:last-child {{ border-bottom: none; }}
        .takeaway-list li::before {{
            content: counter(takeaway);
            position: absolute;
            left: 0;
            top: 20px;
            width: 40px;
            height: 40px;
            background: var(--primary);
            color: white;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
        }}
        .data-note {{
            background: #ebf8ff;
            border: 1px solid #90cdf4;
            padding: 16px 20px;
            border-radius: 8px;
            margin-top: 40px;
            font-size: 0.9rem;
            color: #2c5282;
        }}
        .footer {{
            text-align: center;
            padding: 40px 0;
            margin-top: 60px;
            border-top: 1px solid #e2e8f0;
            color: var(--secondary);
            font-size: 0.9rem;
        }}
        @media (max-width: 768px) {{
            h1 {{ font-size: 2rem; }}
            .section {{ padding: 24px; }}
            .kpi-grid {{ grid-template-columns: 1fr 1fr; }}
        }}
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>Nine Decades of Oscar-Winning Scores</h1>
            <p class="subtitle">A Historical Trend Analysis (1934–2026)</p>
        </header>

        <section class="section">
            <h2>Dataset Overview & Historical Context</h2>
            <p>This report analyzes every Academy Award winner for Best Original Score across {total_ceremonies} ceremonies, spanning from the 6th Academy Awards in 1934 through the 98th ceremony in March 2026. The dataset captures the evolution of film music's highest honor across nine decades, revealing patterns of composer dominance, stylistic shifts, and the changing landscape of cinematic scoring.</p>

            <h3>Key Performance Indicators</h3>
            <div class="kpi-grid">
                <div class="kpi-card">
                    <div class="kpi-value">{total_unique_composers}</div>
