    html += f'<tr><td>{r["Year"]}</td><td>{r["Film"]}</td><td>{r["Composer"]}</td></tr>\n'

html += '''                </tbody>
            </table>
        </section>

        <section class="section">
            <h2>Key Takeaways & Forward-Looking Observations</h2>
            <ol class="takeaway-list">
