import pandas as pd
df = pd.read_csv('/app/benchmark/data.csv')

def parse_composers(s):
    return [c.strip() for c in s.split(',')]

# Count composer wins
all_composers = []
for _, row in df.iterrows():
    all_composers.extend(parse_composers(row['Composer']))

from collections import Counter
wins = Counter(all_composers)
print('Top 10 composers by wins:')
for c, w in wins.most_common(10):
    print(f'  {c}: {w}')

# Repeat winner rate - % of ceremonies with repeat winners
composer_years = {}
for _, row in df.iterrows():
    for c in parse_composers(row['Composer']):
        if c not in composer_years:
            composer_years[c] = []
        composer_years[c].append(row['Year'])

repeat_ceremonies = 0
for c, years in composer_years.items():
    if len(years) > 1:
        # First win doesn't count as repeat, subsequent wins do
        repeat_ceremonies += len(years) - 1

print(f'\\nTotal ceremonies: {len(df)}')
print(f'Repeat wins (ceremonies won by composers who had won before): {repeat_ceremonies}')
print(f'Repeat winner rate: {repeat_ceremonies/len(df)*100:.1f}%')
"

